  const scriptHash = getGopParticipationBatchTemplateHash();
  let offset = 0;
  const limit = 100;
  let moreAvailable = true;
  while (moreAvailable) {
    const url = `${get_store_value(explorer_uri)}/api/v1/boxes/unspent/search`;
    try {
      const response = await fetch(`${url}?offset=${offset}&limit=${limit}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ergoTreeTemplateHash: scriptHash,
          registers: {
            R6: gameNftId
          }
        })
      });
      if (!response.ok)
        throw new Error(`API response: ${response.status}`);
      const data = await response.json();
      const items = data.items || [];
      for (const box of items) {
        if (box.additionalRegisters?.R6?.renderedValue === gameNftId) {
          batches.push(box);
        }
      }
      offset += items.length;
      moreAvailable = items.length === limit;
    } catch (error) {
      console.error("Exception while fetching participation batches:", error);
      moreAvailable = false;
    }
  }
  return batches;
