function deriveGamePhaseSnapshot(game, currentHeight) {
  if (!game) {
    return {
      currentHeight,
      openCeremony: false,
      openSolverSubmit: false,
      participationIsEnded: false,
      resolutionAllowed: false,
      gameSuspended: false,
      subphase: GameUiSubphase.UNKNOWN,
      ...GAME_PHASE_DEFINITIONS[GameUiSubphase.UNKNOWN]
    };
  }
  const activeGame = game.status === GameState.Active ? game : null;
  const openCeremony = !!activeGame && currentHeight < activeGame.ceremonyDeadline;
  const openSolverSubmit = !!activeGame && currentHeight < activeGame.ceremonyDeadline - activeGame.constants.SEED_MARGIN;
  const participationIsEnded = game.status !== GameState.Active || currentHeight >= game.deadlineBlock;
  const resolutionAllowed = game.status === GameState.Active && currentHeight >= game.deadlineBlock && currentHeight < game.deadlineBlock + game.constants.PARTICIPATION_GRACE_PERIOD;
  const gameSuspended = game.status === GameState.Active && currentHeight >= game.deadlineBlock + game.constants.PARTICIPATION_GRACE_PERIOD;
  let subphase = GameUiSubphase.UNKNOWN;
  if (game.status === GameState.Finalized) {
    subphase = GameUiSubphase.FINALIZED;
  } else if (game.status === GameState.Cancelled_Draining) {
    subphase = currentHeight >= game.unlockHeight ? GameUiSubphase.CANCELLED_DRAINING : GameUiSubphase.CANCELLED_LOCKED;
  } else if (game.status === GameState.Resolution) {
    subphase = currentHeight >= game.resolutionDeadline ? GameUiSubphase.READY_TO_FINALIZE : GameUiSubphase.JUDGING;
  } else if (game.status === GameState.Active) {
    if (gameSuspended) {
      subphase = GameUiSubphase.SUSPENDED;
    } else if (participationIsEnded) {
      subphase = GameUiSubphase.AWAITING_RESOLUTION;
    } else if (openCeremony && openSolverSubmit) {
      subphase = GameUiSubphase.STRATEGY_UPLOAD;
    } else if (openCeremony) {
      subphase = GameUiSubphase.SEED_LOCKDOWN;
    } else {
      subphase = GameUiSubphase.PLAYING;
    }
  }
  return {
    currentHeight,
    openCeremony,
    openSolverSubmit,
    participationIsEnded,
    resolutionAllowed,
    gameSuspended,
    subphase,
    ...GAME_PHASE_DEFINITIONS[subphase]
  };
}
